use std::process::ExitCode;

use wgpu::util::DeviceExt;

const WORKGROUP: u32 = 16;

const SHADER: &str = r#"
struct Dims {
    width: u32,
    height: u32,
};

@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

fn cell(x: i32, y: i32) -> u32 {
    if (x < 0 || y < 0 || x >= i32(dims.width) || y >= i32(dims.height)) {
        return 0u;
    }
    return src[u32(y) * dims.width + u32(x)];
}

@compute @workgroup_size(16, 16, 1)
fn step(@builtin(global_invocation_id) id: vec3<u32>) {
    if (id.x >= dims.width || id.y >= dims.height) {
        return;
    }
    let x = i32(id.x);
    let y = i32(id.y);
    var n = 0u;
    for (var dy = -1; dy <= 1; dy++) {
        for (var dx = -1; dx <= 1; dx++) {
            if (dx != 0 || dy != 0) {
                n += cell(x + dx, y + dy);
            }
        }
    }
    let idx = id.y * dims.width + id.x;
    let alive = src[idx];
    var next = 0u;
    if (n == 3u || (alive == 1u && n == 2u)) {
        next = 1u;
    }
    dst[idx] = next;
}
"#;

struct Grid {
    width: u32,
    height: u32,
    generations: u32,
    cells: Vec<u32>,
}

fn parse(text: &str) -> Result<Grid, String> {
    let mut lines = text.lines().filter(|l| !l.trim().is_empty());
    let header = lines.next().ok_or("empty input")?;
    let nums: Vec<u32> = header
        .split_whitespace()
        .map(|t| t.parse::<u32>().map_err(|_| format!("bad header value: {t}")))
        .collect::<Result<_, _>>()?;
    let [width, height, generations] = nums[..] else {
        return Err("header must be: <width> <height> <generations>".into());
    };
    if !(1..=512).contains(&width) || !(1..=512).contains(&height) {
        return Err("width and height must be between 1 and 512".into());
    }
    if generations > 1000 {
        return Err("generations must be between 0 and 1000".into());
    }
    let mut cells = Vec::with_capacity((width * height) as usize);
    for row in 0..height {
        let line = lines.next().ok_or(format!("missing row {}", row + 1))?;
        let before = cells.len();
        for tok in line.split_whitespace() {
            match tok {
                "0" => cells.push(0),
                "1" => cells.push(1),
                _ => return Err(format!("bad cell '{tok}' in row {}", row + 1)),
            }
        }
        if cells.len() - before != width as usize {
            return Err(format!("row {} does not have {width} cells", row + 1));
        }
    }
    if lines.next().is_some() {
        return Err("more rows than the height".into());
    }
    Ok(Grid { width, height, generations, cells })
}

fn run_gpu(grid: &Grid) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle_from_env());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
        power_preference: wgpu::PowerPreference::HighPerformance,
        ..Default::default()
    }))
    .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
        .map_err(|e| format!("no GPU device: {e}"))?;

    let size = (grid.cells.len() * std::mem::size_of::<u32>()) as wgpu::BufferAddress;
    let dims = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("dims"),
        contents: &[grid.width.to_ne_bytes(), grid.height.to_ne_bytes()].concat(),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let cell_bytes: Vec<u8> = grid.cells.iter().flat_map(|c| c.to_ne_bytes()).collect();
    let storage = wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST;
    let buffers = [
        device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("cells a"),
            contents: &cell_bytes,
            usage: storage,
        }),
        device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("cells b"),
            size,
            usage: storage,
            mapped_at_creation: false,
        }),
    ];
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("life"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("life"),
        layout: None,
        module: &module,
        entry_point: Some("step"),
        compilation_options: Default::default(),
        cache: None,
    });
    let layout = pipeline.get_bind_group_layout(0);
    // bind_groups[i] reads buffers[i] and writes buffers[1 - i].
    let bind_groups: Vec<wgpu::BindGroup> = (0..2)
        .map(|i| {
            device.create_bind_group(&wgpu::BindGroupDescriptor {
                label: None,
                layout: &layout,
                entries: &[
                    wgpu::BindGroupEntry { binding: 0, resource: dims.as_entire_binding() },
                    wgpu::BindGroupEntry { binding: 1, resource: buffers[i].as_entire_binding() },
                    wgpu::BindGroupEntry { binding: 2, resource: buffers[1 - i].as_entire_binding() },
                ],
            })
        })
        .collect();

    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
    let groups_x = grid.width.div_ceil(WORKGROUP);
    let groups_y = grid.height.div_ceil(WORKGROUP);
    for generation in 0..grid.generations as usize {
        // A separate pass per generation so each one sees the previous one's complete output.
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor::default());
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_groups[generation % 2], &[]);
        pass.dispatch_workgroups(groups_x, groups_y, 1);
    }
    let result = &buffers[grid.generations as usize % 2];
    encoder.copy_buffer_to_buffer(result, 0, &readback, 0, size);
    queue.submit([encoder.finish()]);

    let (tx, rx) = std::sync::mpsc::channel();
    readback.slice(..).map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    rx.recv()
        .map_err(|e| format!("map callback dropped: {e}"))?
        .map_err(|e| format!("buffer map failed: {e}"))?;
    let cells = {
        let data = readback.slice(..).get_mapped_range();
        data.chunks_exact(4)
            .map(|b| u32::from_ne_bytes([b[0], b[1], b[2], b[3]]))
            .collect()
    };
    readback.unmap();
    Ok(cells)
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: gpu_life <input-file>");
        return ExitCode::from(2);
    };
    let text = match std::fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("cannot read {path}: {e}");
            return ExitCode::from(1);
        }
    };
    let grid = match parse(&text) {
        Ok(g) => g,
        Err(e) => {
            eprintln!("invalid input: {e}");
            return ExitCode::from(1);
        }
    };
    let cells = match run_gpu(&grid) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("{e}");
            return ExitCode::from(1);
        }
    };

    let mut out = String::with_capacity(cells.len() * 2 + 32);
    for row in cells.chunks(grid.width as usize) {
        let digits: Vec<&str> = row.iter().map(|&c| if c == 1 { "1" } else { "0" }).collect();
        out.push_str(&digits.join(" "));
        out.push('\n');
    }
    let alive = cells.iter().filter(|&&c| c == 1).count();
    out.push_str(&format!("ALIVE {alive}\n"));
    print!("{out}");
    ExitCode::SUCCESS
}

